[PHP]
function parse_username($username)
{
    $username = $username[1];
    $row = DB()->fetch_row("SELECT user_id, user_rank FROM ". BB_USERS ." WHERE username = '". DB()->escape($username) ."'");
    if($row) $username = '<a href="'. PROFILE_URL . $row['user_id'] .'">'. $username .'</a>';
    return $username;
}
[/PHP]
после вставляем:
[PHP]
function commands_to_text($message, $user_id)
{
    $username = $txt = '';

    $row = DB()->fetch_row("SELECT username, user_rank, user_id FROM ". BB_USERS ." WHERE user_id = '". DB()->escape($user_id) ."'");
    if($row) $username = '<a href="'. PROFILE_URL . $row['user_id'] .'">'. $row['username'].'</a>';

    preg_match_all('#\/(.*?) ([\S].*)#', $message, $command, PREG_SET_ORDER);

    switch(@$command[0][1])
    {
        case 'me':
            $txt = $username.' '.$command[0][2];

            return ['type' => 1,'txt' => $txt];

            break;

        case 'a':
            $txt = $username.' отвечает на вопрос викторины: '.$command[0][2];

            return ['type' => 2, 'txt' => $txt];
            break;

        default:
            return false;

    }

}
[/PHP]
